function dist(a: { worldX?: number; worldZ?: number; x?: number; z?: number }, x: number, z: number) {
    const px = a.worldX ?? a.x ?? 0;
    const pz = a.worldZ ?? a.z ?? 0;
    return Math.max(Math.abs(px - x), Math.abs(pz - z));
}

